-- TRUSTD anonymous leaderboard setup. Run in the Supabase SQL Editor.\n-- These policies intentionally allow public, unverified submissions. Scores are not trustworthy.\n\ncreate table if not exists public.quiz_submissions (\n  id bigint generated by default as identity primary key,\n  quiz_id text not null,\n  quiz_title text not null,\n  creator_name text not null,\n  player_name text not null,\n  score integer not null check (score >= 0),\n  total integer not null check (total > 0 and total <= 20),\n  created_at timestamptz not null default now()\n);\n\nalter table public.quiz_submissions enable row level security;\n\ndrop policy if exists "Anyone can view quiz submissions" on public.quiz_submissions;\ncreate policy "Anyone can view quiz submissions" on public.quiz_submissions\n  for select to anon, authenticated using (true);\n\ndrop policy if exists "Anyone can submit quiz scores" on public.quiz_submissions;\ncreate policy "Anyone can submit quiz scores" on public.quiz_submissions\n  for insert to anon, authenticated with check (\n    length(player_name) between 1 and 24\n    and length(creator_name) between 1 and 40\n    and length(quiz_title) between 1 and 100\n    and score <= total\n  );\n\ngrant select, insert on public.quiz_submissions to anon, authenticated;\n